/* cppi::e93fd4b362a533c940f8af83d07029980e5fa4be4b291f39004eef86a669be02 */
select business_date as date_, security_id, 'SP500_30' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-24' and business_date <= date '2025-06-24' and weight_ndo>0 and id_cppib_index = 'SP500_30_GR_USD_0_0' and security_id is not null

